/* RiskLink01Mapper.countUserSiteAuth */
SELECT
    COUNT(1)
FROM TB_USER_SITE_AUTH A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.USER_CD = #{userCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'

/* RiskLink01Mapper.selectAvailableNearMiss */
SELECT

FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{gvCmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.USE_YN = 'Y'
  AND A.REPORT_STATUS_CD = '400'
  AND NOT EXISTS (
        SELECT 1
        FROM TB_RISK_NEAR_MISS_LINK L
        WHERE L.CMPNY_CD = A.CMPNY_CD
          AND L.SITE_CD = A.SITE_CD
          AND L.NEAR_MISS_ID = A.NEAR_MISS_ID
          AND L.PROCESS_CD = #{processCd}
          AND L.ASSESSMENT_CD = #{assessmentCd}
          AND L.USE_YN = 'Y'
      )

    AND (
            A.DESCRIPTION LIKE CONCAT('%', #{keyword}, '%')
         OR A.LOCATION_DESC LIKE CONCAT('%', #{keyword}, '%')
        )

ORDER BY A.OCCUR_DTIME DESC, A.NEAR_MISS_ID DESC

/* RiskLink01Mapper.selectLinkedNearMiss */
SELECT

FROM TB_RISK_NEAR_MISS_LINK L
     INNER JOIN TB_NEAR_MISS A
        ON (
            L.CMPNY_CD = A.CMPNY_CD
        AND L.SITE_CD = A.SITE_CD
        AND L.NEAR_MISS_ID = A.NEAR_MISS_ID
        AND A.USE_YN = 'Y'
        )
WHERE L.CMPNY_CD = #{gvCmpnyCd}
  AND L.SITE_CD = #{siteCd}
  AND L.PROCESS_CD = #{processCd}
  AND L.ASSESSMENT_CD = #{assessmentCd}
  AND L.USE_YN = 'Y'
ORDER BY A.OCCUR_DTIME DESC, A.NEAR_MISS_ID DESC

/* RiskLink01Mapper.selectAssessmentStatus */
SELECT
    A.ASSESSMENT_STATUS
FROM TB_RISK_ASSESSMENT A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.PROCESS_CD = #{processCd}
  AND A.ASSESSMENT_CD = #{assessmentCd}

/* RiskLink01Mapper.selectNearMissReportStatus */
SELECT
    A.REPORT_STATUS_CD
FROM TB_NEAR_MISS A
WHERE A.CMPNY_CD = #{cmpnyCd}
  AND A.SITE_CD = #{siteCd}
  AND A.NEAR_MISS_ID = #{nearMissId}
  AND A.USE_YN = 'Y'

/* RiskLink01Mapper.countLink */
SELECT
    COUNT(1)
FROM TB_RISK_NEAR_MISS_LINK L
WHERE L.CMPNY_CD = #{gvCmpnyCd}
  AND L.SITE_CD = #{siteCd}
  AND L.PROCESS_CD = #{processCd}
  AND L.ASSESSMENT_CD = #{assessmentCd}
  AND L.NEAR_MISS_ID = #{nearMissId}

mapper.insert:
/* RiskLink01Mapper.insertLink */
INSERT INTO TB_RISK_NEAR_MISS_LINK
(
    CMPNY_CD
  , SITE_CD
  , PROCESS_CD
  , ASSESSMENT_CD
  , NEAR_MISS_ID
  , USE_YN
  , INSERT_NO
  , INSERT_DATE
)
VALUES
(
    #{gvCmpnyCd}
  , #{siteCd}
  , #{processCd}
  , #{assessmentCd}
  , #{nearMissId}
  , 'Y'
  , #{gvUserCd}
  , NOW()
)

mapper.update:
/* RiskLink01Mapper.restoreLink */
UPDATE TB_RISK_NEAR_MISS_LINK
SET
    USE_YN      = 'Y'
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND NEAR_MISS_ID = #{nearMissId}

/* RiskLink01Mapper.updateLinkUseYn */
UPDATE TB_RISK_NEAR_MISS_LINK
SET
    USE_YN      = 'N'
  , UPDATE_NO   = #{gvUserCd}
  , UPDATE_DATE = NOW()
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND PROCESS_CD = #{processCd}
  AND ASSESSMENT_CD = #{assessmentCd}
  AND NEAR_MISS_ID = #{nearMissId}
  AND USE_YN = 'Y'
